def find_connected_components_4way(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    comps = []

    def get_cells(r, c, val):
        cells = [(r, c)]
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            cr, cc = stack.pop()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                    if grid[nr][nc] == val:
                        visited[nr][nc] = True
                        stack.append((nr, nc))
                        cells.append((nr, nc))
        return cells

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                cells = get_cells(r, c, grid[r][c])
                comps.append({'val': grid[r][c], 'cells': cells})
                print(f"Component val={grid[r][c]}: {cells}")

    return comps

